#!/usr/bin/env bash
#
# add-operator.sh — create a named operator account.
#
# WHY THIS EXISTS
#
# A deployment starts with ONE account, the administrator email given to the
# installer, whose password is
# generated by the installer. If the NOC and the SOC share it, the audit log —
# which is HMAC-chained, append-only and verifiable — records "admin" for every
# action and cannot answer the only question an audit log is asked: who did this.
# Every other control in the product survives that; attribution does not.
#
# So this is not a convenience script. It is the step that makes the audit trail
# mean something, and it should be run once per person before handover.
#
# Roles (least privilege first — give the smallest one that lets someone work):
#
#   auditor  read events, the audit log and reports. NO configuration changes.
#            The right role for a SOC analyst who triages and escalates.
#   viewer   read-only across the console.
#   editor   onboard and tune sites, manage rules and exclusions. Cannot manage
#            users or API keys. The right role for NOC operations.
#   admin    everything except tenant ownership, including user management.
#   owner    full control.
#
# Usage:
#   ./add-operator.sh                                  # prompts for everything
#   ./add-operator.sh --email a.sinha@esds.co.in \
#                     --name "Ayush Sinha" --role editor
#
# The password is GENERATED, printed once, and never stored by this script.
# Hand it over on a secure channel and have the person change it immediately
# (Settings -> Your password); a reset link needs SMTP, which many internal
# deployments deliberately leave unconfigured.

set -uo pipefail

RED=$'\e[31m'; GRN=$'\e[32m'; YEL=$'\e[33m'; DIM=$'\e[2m'; B=$'\e[1m'; R=$'\e[0m'
die() { printf '%s✗%s %s\n' "$RED" "$R" "$1" >&2; exit 1; }
ok()  { printf '  %s✓%s %s\n' "$GRN" "$R" "$1"; }

EMAIL=""; NAME=""; ROLE=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --email) EMAIL="${2:-}"; shift 2;;
    --name)  NAME="${2:-}";  shift 2;;
    --role)  ROLE="${2:-}";  shift 2;;
    -h|--help) sed -n '2,40p' "$0"; exit 0;;
    *) die "unknown argument: $1";;
  esac
done

command -v curl >/dev/null || die "curl is required"
command -v python3 >/dev/null || die "python3 is required"
command -v openssl >/dev/null || die "openssl is required"

# The installer writes the admin password into a 0600 .env beside the compose
# files. Look there rather than asking for it, so this works unattended.
ENV_FILE="${SENTINEL_ENV_FILE:-}"
if [[ -z "$ENV_FILE" ]]; then
  for c in /opt/sentinel/current/.env ./.env ../.env /opt/sentinel-src/deploy/docker/.env; do
    [[ -r "$c" ]] && { ENV_FILE="$c"; break; }
  done
fi
[[ -n "$ENV_FILE" && -r "$ENV_FILE" ]] || die "cannot find a readable .env — set SENTINEL_ENV_FILE"

# The console listens where the installer bound it — SENTINEL_MGMT_BIND in that
# .env ("127.0.0.1:" by default, "<private-ip>:" with --console-bind). Read it
# rather than assume loopback.
MGMT_HOST="$(sed -n 's/^SENTINEL_MGMT_BIND=//p' "$ENV_FILE" 2>/dev/null | head -1 | tr -d ':[:space:]')"
[[ -n "$MGMT_HOST" && "$MGMT_HOST" != "0.0.0.0" ]] || MGMT_HOST=127.0.0.1
API="${SENTINEL_API:-https://${MGMT_HOST}:9443/api/v1}"
# The console login the installer created (SENTINEL_BOOTSTRAP_ADMIN_EMAIL, the
# "Administrator email" it asked for); installs older than that setting use
# the old fixed login.
BOOT_LOGIN="$(sed -n 's/^SENTINEL_BOOTSTRAP_ADMIN_EMAIL=//p' "$ENV_FILE" 2>/dev/null | head -1)"
ADMIN_EMAIL="${SENTINEL_ADMIN_LOGIN:-${BOOT_LOGIN:-admin@sentinel.local}}"
# The ORIGINAL admin password from the .env, which stops working once the admin
# changes it; SENTINEL_ADMIN_PASSWORD overrides it, and a rejected one is asked for.
ADMIN_PW="${SENTINEL_ADMIN_PASSWORD:-$(grep -E '^SENTINEL_BOOTSTRAP_ADMIN_PASSWORD=' "$ENV_FILE" 2>/dev/null | cut -d= -f2- | tr -d '\r\n')}"
if [[ -z "$ADMIN_PW" ]]; then
  read -r -s -p "Administrator password for $ADMIN_EMAIL: " ADMIN_PW; echo
fi
[[ -n "$ADMIN_PW" ]] || die "no administrator password available"

[[ -n "$EMAIL" ]] || read -r -p "Email (the person's real work address): " EMAIL
[[ "$EMAIL" == *@*.* ]] || die "\"$EMAIL\" is not an email address"
[[ -n "$NAME" ]]  || read -r -p "Full name: " NAME
[[ -n "$NAME" ]]  || die "a name is required — it is what appears in the audit log"
if [[ -z "$ROLE" ]]; then
  printf '%sRole%s — auditor (SOC, read-only) | editor (NOC, can onboard sites) | viewer | admin | owner\n' "$B" "$R"
  read -r -p "Role [auditor]: " ROLE; ROLE="${ROLE:-auditor}"
fi
case "$ROLE" in
  owner|admin|editor|viewer|auditor) ;;
  *) die "invalid role \"$ROLE\" — one of: owner admin editor viewer auditor";;
esac

admin_login() { curl -sk -X POST "$API/auth/login" -H 'Content-Type: application/json' \
  -d "$(python3 -c 'import json,sys; print(json.dumps({"email":sys.argv[1],"password":sys.argv[2]}))' "$ADMIN_EMAIL" "$1")" \
  | python3 -c 'import sys,json; print(json.load(sys.stdin).get("access_token",""))' 2>/dev/null; }
TOKEN="$(admin_login "$ADMIN_PW")"
if [[ -z "$TOKEN" && -t 0 ]]; then
  printf 'The original password in %s no longer works for %s (changed — good).\n' "$ENV_FILE" "$ADMIN_EMAIL"
  read -r -s -p "Current password for $ADMIN_EMAIL: " ADMIN_PW; echo
  TOKEN="$(admin_login "$ADMIN_PW")"
fi
[[ -n "$TOKEN" ]] || die "could not authenticate as $ADMIN_EMAIL — if its password was changed, run with SENTINEL_ADMIN_PASSWORD=<current password>"
ok "authenticated as $ADMIN_EMAIL"

# 20 random chars plus one of each required class. The product's floor is 12 and
# at least two character classes; this clears both by a wide margin.
PW="$(openssl rand -base64 18 | tr -d '/+=' | cut -c1-20)Aa9!"

BODY="$(python3 -c 'import json,sys; print(json.dumps({"email":sys.argv[1],"name":sys.argv[2],"role":sys.argv[3],"password":sys.argv[4]}))' \
  "$EMAIL" "$NAME" "$ROLE" "$PW")"
RESP="$(mktemp)"; trap 'rm -f "$RESP"' EXIT
CODE="$(curl -sk -o "$RESP" -w '%{http_code}' -X POST "$API/admin/users" \
  -H "Authorization: Bearer $TOKEN" -H 'Content-Type: application/json' -d "$BODY")"

case "$CODE" in
  201) ok "account created" ;;
  409) die "an account for $EMAIL already exists" ;;
  403) die "this administrator may not create users" ;;
  *)   die "create failed (HTTP $CODE): $(head -c 300 "$RESP")" ;;
esac

# Prove the account works instead of trusting the 201 — a created-but-unusable
# account is worse than a failed create, because nobody finds out until handover.
VTOK="$(curl -sk -X POST "$API/auth/login" -H 'Content-Type: application/json' \
  -d "$(python3 -c 'import json,sys; print(json.dumps({"email":sys.argv[1],"password":sys.argv[2]}))' "$EMAIL" "$PW")" \
  | python3 -c 'import sys,json; print(json.load(sys.stdin).get("access_token",""))' 2>/dev/null)"
[[ -n "$VTOK" ]] || die "account was created but cannot log in — investigate before handing it over"
ok "login verified"

printf '\n%s%s  %s\n' "$B" "$NAME" "$R"
printf '  email     %s\n' "$EMAIL"
printf '  role      %s\n' "$ROLE"
printf '  password  %s%s%s\n' "$B" "$PW" "$R"
printf '\n%sShown once and not stored by this script.%s\n' "$YEL" "$R"
printf '%sHand it over on a secure channel and have them change it at\n' "$DIM"
printf 'Settings -> Your password. Their name now appears in the audit log for\n'
printf 'everything they do, which is the reason this account exists.%s\n' "$R"
